#include <iostream>
#include <utility>

class SimpleArray {
private:
    std::size_t size{0};
    int *ptr{nullptr};

public:
    explicit SimpleArray(std::size_t s = 5) : size{s}, ptr{new int[s]} {
        for (std::size_t i = 0; i < size; ++i) ptr[i] = 0;
    }

    // Copy constructor (Deep Copy)
    SimpleArray(const SimpleArray &other) : size{other.size}, ptr{new int[other.size]} {
        for (std::size_t i = 0; i < size; ++i) ptr[i] = other.ptr[i];
    }

    // Overloaded assignment operator
    SimpleArray &operator=(const SimpleArray &other) {
        if (this != &other) { // Guard against self-assignment
            if (size != other.size) {
                delete[] ptr;
                size = other.size;
                ptr = new int[size];
            }
            for (std::size_t i = 0; i < size; ++i) ptr[i] = other.ptr[i];
        }
        return *this;
    }

    ~SimpleArray() { delete[] ptr; }

    std::size_t getSize() const { return size; }
    void set(std::size_t i, int val) { if (i < size) ptr[i] = val; }
    int get(std::size_t i) const { return ptr[i]; }
};

int main() {
    SimpleArray arr1(3);
    arr1.set(0, 10); arr1.set(1, 20); arr1.set(2, 30);

    SimpleArray arr2 = arr1; // Copy constructor
    SimpleArray arr3(5);
    arr3 = arr1;             // Assignment operator with resize

    std::cout << "arr2 size: " << arr2.getSize() << ", arr2[1]: " << arr2.get(1) << "\n";
    std::cout << "arr3 size: " << arr3.getSize() << ", arr3[2]: " << arr3.get(2) << "\n";
    return 0;
}

body.vi:
Toán tử so sánh bằng `operator==` trước hết kiểm tra xem hai mảng có cùng kích thước (`size == right.size`) hay không; nếu kích thước khác nhau thì lập tức trả về `false`. Sau đó, nó duyệt qua từng phần tử tương ứng bằng vòng lặp và so sánh giá trị.
Thay vì viết lại toàn bộ vòng lặp cho toán tử khác nhau `operator!=`, ta định nghĩa hàm inline gọn gàng:
```cpp
bool operator!=(const Array &right) const {
    return !(*this == right);
}
```
Cách làm này đảm bảo tính nhất quán (consistency), giảm trùng lặp mã và tự động cập nhật nếu logic so sánh bằng thay đổi.

body.en:
The equality operator `operator==` first checks whether both arrays have identical sizes (`size == right.size`); if not, it immediately returns `false`. It then iterates through all corresponding elements to verify value equality.
Rather than duplicating iteration logic for inequality `operator!=`, it is implemented cleanly as an inline member:
```cpp
bool operator!=(const Array &right) const {
    return !(*this == right);
}
```
This design pattern guarantees consistency, avoids code duplication, and automatically reflects any changes made to `operator==`.

