#include <iostream>
#include <stdexcept>

class SafeArray {
private:
    std::size_t size{0};
    int *ptr{nullptr};

public:
    explicit SafeArray(std::size_t s) : size{s}, ptr{new int[s]} {
        for (std::size_t i = 0; i < size; ++i) ptr[i] = 0;
    }
    ~SafeArray() { delete[] ptr; }

    // Non-const subscript operator (modifiable lvalue)
    int &operator[](int index) {
        if (index < 0 || static_cast<std::size_t>(index) >= size) {
            throw std::out_of_range("Subscript out of range");
        }
        return ptr[index];
    }

    // Const subscript operator (rvalue / read-only)
    int operator[](int index) const {
        if (index < 0 || static_cast<std::size_t>(index) >= size) {
            throw std::out_of_range("Subscript out of range");
        }
        return ptr[index];
    }

    bool operator==(const SafeArray &right) const {
        if (size != right.size) return false;
        for (std::size_t i = 0; i < size; ++i) {
            if (ptr[i] != right.ptr[i]) return false;
        }
        return true;
    }

    bool operator!=(const SafeArray &right) const {
        return !(*this == right);
    }
};

int main() {
    SafeArray a(3);
    a[0] = 100; // Modifiable lvalue
    a[1] = 200;
    a[2] = 300;

    const SafeArray &constRef = a;
    std::cout << "constRef[1]: " << constRef[1] << "\n";

    SafeArray b(3);
    b[0] = 100; b[1] = 200; b[2] = 300;
    std::cout << "a == b? " << (a == b ? "true" : "false") << "\n";

    try {
        a[10] = 500; // Trigger out of range exception
    } catch (const std::out_of_range &ex) {
        std::cout << "Caught exception: " << ex.what() << "\n";
    }
    return 0;
}
